// @lab {"title": "Footage layer spike (D-114): a synthetic clip seeked (never played) per frame, graded duotone from tokens, with a label; mono and ungraded beside it", "styles": ["story-cartoon", "corporate-clean"], "dur": 4.0, "times": [0.3, 0.8, 1.6, 2.2, 3.0, 3.8]}
// A lab scene for Loom.footage. The clip is scenes_examples/lab/media/synthetic_bars.webm (ffmpeg testsrc2 with a
// moving block, VP9, 48 KB; no real footage). The lab page cannot reach that folder (loom/lab.py copies only scripts),
// so the same bytes ride here as a data URI at the end of this file, written by
// `python3 tests/suites/primitives_material_footage_hands.py --sync-footage` (a test keeps them equal). The big clip must change between
// strip frames (it is seeked to t), and two renders of the same time must be identical.
Loom.scene("lab_footage", {
  build(ctx) {
    const clip = LAB_FOOTAGE_CLIP;
    Loom.footage(ctx, "duotone", { src: clip, x: 160, y: 150, w: 960, h: 540, trim: [0, 4], at: 0, grade: { duotone: ["ink", "accent2"] },
      overlays: [{ text: "duotone: ink to accent2", x: 24, y: 24, w: 420 }] });
    Loom.footage(ctx, "mono", { src: clip, x: 1200, y: 150, w: 560, h: 315, trim: [0, 4], at: 0, grade: { mono: true },
      overlays: [{ text: "mono", x: 16, y: 16, w: 140 }] });
    Loom.footage(ctx, "plain", { src: clip, x: 1200, y: 505, w: 560, h: 185, trim: [1, 3], at: 1, fit: "cover",
      overlays: [{ text: "ungraded, trim [1, 3] at 1 s", x: 16, y: 16, w: 400 }] });
    ctx.kit.text(ctx.g, "the clip is seeked to t on every frame; it never plays", { x: 160, y: 720, w: 1600, h: 50, role: "label", align: "left", color: "muted" });
  },
});
/* @clip-begin */
var LAB_FOOTAGE_CLIP = "data:video/webm;base64,";
/* @clip-end */
